import os,subprocess
D='/tmp/probe/bigdb2'
env=dict(os.environ); env['_ZO_DATA_DIR']=D
st0=os.stat(D+'/db.zo'); print("before ino=%d size=%d"%(st0.st_ino,st0.st_size))
p=subprocess.Popen(['/workspace/executable','add','/tmp/probe/dirs/beta'],env=env)
obs=set(); tmpsizes=[]
while p.poll() is None:
    try:
        st=os.stat(D+'/db.zo'); obs.add((st.st_ino,st.st_size))
    except Exception as e: obs.add(('missing',str(e)))
    for f in os.listdir(D):
        if f.startswith('tmp_'):
            try: tmpsizes.append(os.stat(D+'/'+f).st_size)
            except: pass
st1=os.stat(D+'/db.zo'); print("after ino=%d size=%d"%(st1.st_ino,st1.st_size))
print("db.zo observed states during write:",sorted(obs))
print("tmp size samples: min=%s max=%s n=%d"%(min(tmpsizes) if tmpsizes else None,max(tmpsizes) if tmpsizes else None,len(tmpsizes)))
EOF
